  async function upload(existing?: SupplierDocumentEvidence) { if (!draft || draft.draft.state !== 'draft' || !file || !evidenceLoaded || !canFinish || commandLocked || !fresh || review || unresolvedUpload) return; const chosenFile = file, owner = draft.draft; await work(async (valid, signal) => { supplierDocumentFileAllowed(chosenFile); setEvidenceLoaded(false); closeOriginal(); setSeen(null); const verified = () => valid() && sessionTiming(account.session, performance.now() - account.observedAt).fresh; if (existing && (existing.state !== 'fresh' || Date.parse(existing.expiresAt) <= now)) throw new RequestNotSentError(409, 'supplier_document_view_stale'); keyPrefix.current = `sde.${owner.id}`; const reservation = existing ?? await submitTrackedRequest(mutations(), recovery.journal, account.actorId, 'supplier-document-evidence-reserve', 'evidence.supplier-document-image.reserve', { draftId: owner.id, revision: owner.version }, key => gateway.reserve(account.actorId, owner.id, key, verified)); if (!verified()) return; let failure: unknown = null; try { await gateway.upload(account.actorId, owner.id, reservation.reservationId, reservation.revision, chosenFile, verified); } catch (error) { failure = error; } if (!valid()) return; setFile(null); if (fileInput.current) fileInput.current.value = ''; const images = await gateway.evidence(account.actorId, owner.id, null, signal); if (valid()) { setEvidence(images); setEvidenceMore(images.length === 25); setEvidenceLoaded(true); } if (failure !== null && !images.some(item => item.reservationId === reservation.reservationId && item.state === 'quarantined')) throw failure; }); }
